(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.015+t*0.25)*20 + Math.cos(y*0.012-t*0.18)*15;
  const w2 = Math.cos(x*0.008-t*0.15)*30 + Math.sin(y*0.01+t*0.22)*25;
  const w3 = Math.sin((x+y)*0.006+t*0.1)*12;
  const sx = x + w1 + w2*0.3, sy = y + w1*0.4 + w2 + w3;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.95],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.05],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*50, 0.075, 2.4, 1.15]
  ];
  let aS = 0, iS = 0, cross = 0;
  for (let i = 0; i < src.length; i++) {
    for (let j = i+1; j < src.length; j++) {
      const [sX,sY,f,sp,amp] = src[i], [sX2,sY2,f2,sp2,amp2] = src[j];
      const d1 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
      const d2 = Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross += Math.sin(d1*f+t*sp)*Math.sin(d2*f2-t*sp2)*amp*amp2*0.3;
    }
    const [sX,sY,f,sp,amp] = src[i];
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w = Math.sin(d*f-t*sp)*amp;
    aS += w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
  }
  aS /= 8; iS /= 8; cross /= 28;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03+ang*5-t*0.8)*0.2;
  const lap = Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin(sx*0.15+sy*0.15+t)*Math.sin(sx*0.1-sy*0.12-t*0.7);
  const reaction = Math.tanh((aS-iS*0.7+bg*0.3+spiral+spiral2+cross*0.5+lap*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const edge = reaction - Math.tanh((aS*0.8-iS*0.6+bg*0.25+spiral*0.8+spiral2+cross*0.4+lap*0.12)*2.0);
  const glow = Math.exp(-Math.abs(reaction)*3)*0.4;
  const blend = reaction*0.6 + cell*0.2 + edge*0.15 + glow*0.05, v = blend*0.5+0.5;
  const pal = [
    [12,8,48],[20,40,95],[18,90,120],[25,150,135],
    [180,190,80],[220,160,60],[200,100,65],[160,50,70],
    [100,25,65],[50,12,55],[12,8,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edgeBoost = Math.abs(edge)>0.15?1.12:1.0;
  const glowBoost = 1.0+glow*0.6;
  const m = lum*edgeBoost*glowBoost;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
